import { buildProps, definePropType, isArray } from '@element-plus/utils'

import type { ExtractPropTypes, __ExtractPublicPropTypes } from 'vue'
import type { InputPropsPublic } from '@element-plus/components/input'
import type { SelectPropsPublic } from '@element-plus/components/select'

export const inputSelectControlTypes = ['input', 'select'] as const

export type InputSelectControl = (typeof inputSelectControlTypes)[number]
export type InputSelectLayout =
  | ['input', 'select']
  | ['select', 'select']
  | ['select', 'input']
  | ['input', 'input']
export type InputSelectValue =
  | InputPropsPublic['modelValue']
  | SelectPropsPublic['modelValue']
export type InputSelectControlProps =
  | Partial<Omit<InputPropsPublic, 'modelValue'>>
  | Partial<Omit<SelectPropsPublic, 'modelValue'>>

const isInputSelectLayout = (value: unknown): value is InputSelectLayout =>
  isArray(value) &&
  value.length === 2 &&
  value.every((item) =>
    inputSelectControlTypes.includes(item as InputSelectControl)
  )

export const inputSelectProps = buildProps({
  /**
   * @description controls rendered on the left and right
   */
  layout: {
    type: definePropType<InputSelectLayout>(Array),
    default: () => ['select', 'input'] as InputSelectLayout,
    validator: isInputSelectLayout,
  },
  /**
   * @description binding value of the left control
   */
  leftValue: {
    type: definePropType<InputSelectValue>([
      Array,
      String,
      Number,
      Boolean,
      Object,
    ]),
    default: undefined,
  },
  /**
   * @description binding value of the right control
   */
  rightValue: {
    type: definePropType<InputSelectValue>([
      Array,
      String,
      Number,
      Boolean,
      Object,
    ]),
    default: undefined,
  },
  /**
   * @description props passed to the left Input or Select
   */
  leftProps: {
    type: definePropType<InputSelectControlProps>(Object),
    default: () => ({}),
  },
  /**
   * @description props passed to the right Input or Select
   */
  rightProps: {
    type: definePropType<InputSelectControlProps>(Object),
    default: () => ({}),
  },
} as const)

/* eslint-disable @typescript-eslint/no-unused-vars */
export const inputSelectEmits = {
  'update:leftValue': (_value: InputSelectValue) => true,
  'update:rightValue': (_value: InputSelectValue) => true,
  'left-change': (_value: InputSelectValue) => true,
  'right-change': (_value: InputSelectValue) => true,
  'left-focus': (event: FocusEvent) => event instanceof FocusEvent,
  'right-focus': (event: FocusEvent) => event instanceof FocusEvent,
  'left-blur': (event: FocusEvent) => event instanceof FocusEvent,
  'right-blur': (event: FocusEvent) => event instanceof FocusEvent,
  'left-clear': () => true,
  'right-clear': () => true,
  'left-visible-change': (visible: boolean) => typeof visible === 'boolean',
  'right-visible-change': (visible: boolean) => typeof visible === 'boolean',
}
/* eslint-enable @typescript-eslint/no-unused-vars */

export type InputSelectProps = ExtractPropTypes<typeof inputSelectProps>
export type InputSelectPropsPublic = __ExtractPublicPropTypes<
  typeof inputSelectProps
>
export type InputSelectEmits = typeof inputSelectEmits
